import{_ as p,a0 as l,w as u,s as d,ao as s,I as a,x as t,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈 | LCTT x X-CMD","titleTemplate":false,"description":"去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220601 de-Googled -e-OS v1 Released Along with a New Brand -Murena- for Smartphone and Cloud Services","title":"去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈","tag":"202206","desc":""},"relativePath":"202206/20220601 de-Googled -e-OS v1 Released Along with a New Brand -Murena- for Smartphone and Cloud Services.md","filePath":"[post].md"}'),i={name:"202206/20220601 de-Googled -e-OS v1 Released Along with a New Brand -Murena- for Smartphone and Cloud Services.md"};function m(f,e,S,g,T,h){const n=l("Link");return u(),d("div",null,[e[19]||(e[19]=s('<h1 id="去谷歌化操作系統-e-os-v1-及新品牌-murena-一同發佈" tabindex="-1">去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈 <a class="header-anchor" href="#去谷歌化操作系統-e-os-v1-及新品牌-murena-一同發佈" aria-label="Permalink to “去谷歌化操作系統 /e/OS v1 及新品牌 Murena 一同發佈”">​</a></h1><blockquote><p>Murena 是一個與 e 基金會有關的新品牌，該品牌專注於提供隱私友好的 /e/OS 及新的智能手機和雲服務。</p></blockquote><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/06/murena.jpg" alt="murena"></p><p>/e/OS 是一個流行的、注重隱私的移動操作系統，是谷歌安卓的替代品之一。</p><p>這個復刻自 Lineage OS 的操作系統消除了任何與谷歌有關的依賴性，並鼓勵你在使用中不要直接依賴任何谷歌的服務。</p><p>取而代之的是，它提供一些解決方案作為替代品，為你提供一個隱私友好的生態系統。</p><p>為了精簡其產品，負責該操作系統的 e 基金會宣佈了一個新的品牌 “Murena”，其中包括了一些以該操作系統為核心的新功能和一個新的智能手機。</p><h3 id="murena-和-e-基金會" tabindex="-1">Murena 和 e 基金會 <a class="header-anchor" href="#murena-和-e-基金會" aria-label="Permalink to “Murena 和 e 基金會”">​</a></h3><p>e 基金會作為一個致力於 /e/OS 的非營利組織將繼續存在。因此，可以説這不是一次品牌重塑。</p>',9)),a("p",null,[e[1]||(e[1]=t("然而，",-1)),r(n,{href:"https://murena.com/"},{default:o(()=>[...e[0]||(e[0]=[t("Murena",-1)])]),_:1}),e[2]||(e[2]=t(" 作為一個新的創業公司，似乎是一個獨立的商業實體，將專注於鼓勵主流用户嘗試 /e/OS，並促進支持該操作系統的智能手機的使用。",-1))]),e[20]||(e[20]=s('<p>對該公司，/e/OS 的創建者提及：</p><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/06/murena-quote.jpeg" alt=""></p><h3 id="e-os-1-0-有什麼新內容" tabindex="-1">/e/OS 1.0 有什麼新內容？ <a class="header-anchor" href="#e-os-1-0-有什麼新內容" aria-label="Permalink to “/e/OS 1.0 有什麼新內容？”">​</a></h3><p>隨着該操作系統的最新升級發佈，他們的目標是讓事情變得更容易理解，在提高使用便利性的同時，仍然考慮到隱私。</p><p>此外，還隨同本次更新推出了新的應用程序商店（App Lounge）和新的隱私工具（Advanced Privacy）。</p><p><strong>App Lounge</strong>：這個新的應用程序安裝程序可以讓你安裝許多開源應用程序和 PWA（<ruby>漸進式網頁應用<rt>Progress Web App</rt></ruby>）。在你安裝之前，它還會告知你每個應用程序中已有的跟蹤器。</p><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/06/eos-app-lounge-1024x1024.jpg" alt=""></p><p>我相信一個量身定做的應用商店的存在將有助於消除新用户是否應該嘗試用 /e/OS 安裝 Play Store 或 F-Droid 的困惑。</p><p>除此之外，Advanced Privacy 工具將有助於限制用户在安裝第三方應用程序後暴露的數據。</p><p>如果你想遠離科技巨頭，你還會發現 Murena 雲服務可以用作私人電子郵件賬户服務和雲存儲。該電子郵件服務提供的功能可以隱藏你的原始電子郵件地址。</p><h3 id="murena-one" tabindex="-1">Murena One <a class="header-anchor" href="#murena-one" aria-label="Permalink to “Murena One”">​</a></h3><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/06/murena-one-1024x576.jpeg" alt=""></p><p>首款 Murena 品牌的智能手機將於 6 月下旬推出，並將向美國、加拿大、歐洲、英國和瑞士等地的用户發貨。</p><p>這款智能手機將採用 6.5 英寸顯示屏，配備 2500 萬像素的前置攝像頭，後置攝像頭設置有三個傳感器，分別是 4800 萬像素、800 萬像素和 500 萬像素。</p><p>我們不太確定是什麼處理器，但它提到了是一個八核芯片，加上 4GB 的內存。所有這些都由 4500 毫安時的電池供電。</p><p>除了它的第一款智能手機，你還可以從它的官方網站上購買 Fairphone 和 Teracube 的智能手機，這些手機預裝了 /e/OS。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>你可以在其官方網站上了解更多關於新的 /e/OS 升級、雲服務和可用的智能手機的信息。</p>',18)),a("blockquote",null,[a("p",null,[a("strong",null,[r(n,{href:"https://murena.com/"},{default:o(()=>[...e[3]||(e[3]=[t("Murena",-1)])]),_:1})])])]),e[21]||(e[21]=a("p",null,"該智能手機的定價還沒有在新聞發佈會上披露。所以，我們建議你如果有興趣，可以關注一下。",-1)),e[22]||(e[22]=a("hr",null,null,-1)),a("p",null,[e[5]||(e[5]=t("via: ",-1)),r(n,{href:"https://news.itsfoss.com/murena-e-os/"},{default:o(()=>[...e[4]||(e[4]=[t("https://news.itsfoss.com/murena-e-os/",-1)])]),_:1})]),a("p",null,[e[10]||(e[10]=t("作者：",-1)),r(n,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...e[6]||(e[6]=[t("Ankush Das",-1)])]),_:1}),e[11]||(e[11]=t(" 選題：",-1)),r(n,{href:"https://github.com/lkxed"},{default:o(()=>[...e[7]||(e[7]=[t("lkxed",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const O=p(i,[["render",m]]);export{M as __pageData,O as default};
